import{Badge}from'./Badge'
const C:Record<string,{label:string;variant:'default'|'success'|'warning'|'error'|'info'|'accent'}>={DRAFT:{label:'Draft',variant:'default'},SUBMITTED:{label:'Submitted',variant:'info'},DOCUMENTS_VERIFIED:{label:'Docs Verified',variant:'info'},UNDER_REVIEW:{label:'Under Review',variant:'warning'},ADDITIONAL_INFO_REQUESTED:{label:'Info Requested',variant:'warning'},APPROVED:{label:'Approved',variant:'success'},REJECTED:{label:'Rejected',variant:'error'},WITHDRAWN:{label:'Withdrawn',variant:'default'},PENDING:{label:'Pending',variant:'warning'},VERIFIED:{label:'Verified',variant:'success'},EXPIRED:{label:'Expired',variant:'default'},ACTIVE:{label:'Active',variant:'success'},CLOSED:{label:'Closed',variant:'default'},MISSING:{label:'Missing',variant:'error'}}
export function StatusBadge({status}:{status:string}){const cfg=C[status]??{label:status,variant:'default' as const};return<Badge variant={cfg.variant} dot>{cfg.label}</Badge>}
